use App\Models\CmsContent;
use Illuminate\Database\Seeder;

/**
 * Creates the "1st Annual International Conference and Innovation Week 2026"
 * page (slug: conference-2026) if it does not already exist.
 * Safe to run repeatedly — it never overwrites an existing page.
 */
class ConferencePageSeeder extends Seeder
{
    public function run(): void
    {
        $existing = CmsContent::where('slug', 'conference-2026')
            ->where('is_deleted', false)
            ->exists();
        if ($existing) {
            $this->command?->info('conference-2026 page already exists — skipping.');
