{"type": "page", "title": "1st Annual International Conference and Innovation Week 2026", "slug": "conference-2026", "summary": "Science, Innovation and Digital Transformation for Sustainable Socio-Economic Development — 21-23 October 2026, Kaimosi Friends University, Kenya. Hybrid conference (physical and virtual).", "body": "<p><strong>Kaimosi Friends University warmly invites</strong> researchers, innovators, entrepreneurs, industry leaders, policymakers, development partners, students and community organizations from around the world to participate in the 1st Annual International Conference and Innovation Week 2026.</p>\n<p>The conference provides a premier platform for presenting groundbreaking research, displaying innovations, fostering interdisciplinary collaboration, promoting technology transfer and strengthening partnerships that contribute to sustainable socio-economic transformation.</p>\n<p>Whether you are presenting research, exhibiting innovations, networking with experts or exploring emerging technologies, KAFU offers an inspiring environment for knowledge exchange and impactful collaboration.</p>", "status": "published", "structured_data": {"_nav": {"show_in_menu": false, "parent": "__top__", "order": 0}, "blocks": [{"id": "c-stats", "type": "stats", "items": [{"label": "Dates", "value": "21–23 October 2026"}, {"label": "Venue", "value": "Kaimosi Friends University, Kenya"}, {"label": "Format", "value": "Hybrid — Physical & Virtual"}, {"label": "Presentation Fee", "value": "From KES 3,000"}]}, {"id": "c-cta1", "type": "cta", "heading": "Call for Abstracts, Papers, Posters & Innovation Exhibits", "text": "Kaimosi Friends University invites original and unpublished abstracts, research papers, posters and innovative products for presentation during the 1st Annual International Conference and Innovation Week 2026. Selected papers will be considered for publication in the conference proceedings, subject to peer review.", "buttons": [{"label": "Submit Your Abstract", "url": "mailto:conference2026@kafu.ac.ke"}, {"label": "Ask a Question", "url": "mailto:conference2026@kafu.ac.ke"}]}, {"id": "c-cat", "type": "richtext", "html": "<h2>Submission Categories</h2><ul><li>Oral Presentations</li><li>Poster Presentations</li><li>Innovation Exhibitions</li><li>Student Innovations</li><li>Industry Demonstrations</li><li>Community Innovations</li></ul>"}, {"id": "c-themes", "type": "cards", "heading": "Thematic Areas / Sub-Themes", "intro": "Authors are invited to submit abstracts under (but not limited to) the following thematic areas:", "items": [{"title": "Science, Technology and Innovation (STI)", "items": ["Emerging technologies and innovation ecosystems", "Applied sciences for development", "Research commercialization and technology transfer", "Intellectual property and innovation management"]}, {"title": "Digital Transformation, ICT and Artificial Intelligence", "items": ["Artificial intelligence, machine learning and data science", "Cybersecurity and digital governance", "Digital transformation in education, health, agriculture and industry", "Smart systems and digital infrastructure"]}, {"title": "Sustainable Agriculture, Food Security and Bioeconomy", "items": ["Climate-smart agriculture", "Agri-innovation and value addition", "Bioenergy, biofuels and bioproducts", "Food systems resilience and nutrition"]}, {"title": "Climate Change, Environment and Natural Resource Management", "items": ["Climate change mitigation and adaptation", "Biodiversity conservation and ecosystem services", "Environmental chemistry and pollution control", "Renewable energy and circular economy"]}, {"title": "Health Sciences and Biotechnology", "items": ["Public health innovations and policy", "Biotechnology and biomedical research", "Environmental and occupational health", "One Health approaches"]}, {"title": "Education, Pedagogy and Curriculum Innovation", "items": ["STEM education and competency-based education", "Digital learning and educational technologies", "Quality assurance and higher education reforms", "Research supervision and postgraduate training"]}, {"title": "Governance, Leadership and Socio-Economic Development", "items": ["Public policy and governance", "Entrepreneurship, MSMEs and innovation-driven growth", "Gender, equity and social inclusion", "Community engagement and sustainable livelihoods"]}, {"title": "Interdisciplinary Research and Industry–Academia Collaboration", "items": ["Cross-disciplinary research approaches", "University–industry partnerships", "Research-to-policy and research-to-practice pathways"]}]}, {"id": "c-dates", "type": "timeline", "heading": "Important Dates", "items": [{"title": "Call for Abstracts / Exhibitions Opens", "date": "July 13, 2026"}, {"title": "Deadline for Abstract Submission", "date": "August 31, 2026"}, {"title": "Notification of Abstract Acceptance", "date": "Rolling (as received)"}, {"title": "Early Bird Registration Deadline", "date": "September 18, 2026"}, {"title": "Deadline for Registration & Payment", "date": "September 30, 2026"}, {"title": "Conference / Exhibition Dates", "date": "October 21–23, 2026"}]}, {"id": "c-fees", "type": "richtext", "html": "<h2>Registration Fees</h2><table><thead><tr><th>Category</th><th>Fee</th></tr></thead><tbody><tr><td>Research paper oral / poster presentation</td><td>KES 3,000</td></tr><tr><td>Exhibition fees</td><td>KES 10,000</td></tr><tr><td>Exhibition fees for high schools</td><td>KES 3,000</td></tr><tr><td>KAFU staff and students</td><td>Free — no registration fee</td></tr></tbody></table>"}, {"id": "c-guide", "type": "notice", "heading": "Abstract Submission Guidelines", "html": "<ul><li>Abstracts should not exceed <strong>300 words</strong></li><li>Font: Times New Roman, size 12</li><li>Include: Background, Objectives, Methods, Results and Conclusion</li><li>Provide author details: Title, Name(s), Institutional Affiliation, Email Address and Telephone</li><li>Submit to: <a href=\"mailto:conference2026@kafu.ac.ke\">conference2026@kafu.ac.ke</a></li></ul>"}, {"id": "c-pub", "type": "richtext", "html": "<h2>Publications from the Conference</h2><ul><li>Book of abstracts</li><li>Conference proceedings</li><li>The <strong>best five papers</strong> under the health sciences theme will be published in the <em>African Journal of Health Sciences</em> (AJOL) at no cost.</li><li>Up to <strong>20 papers</strong> under education and social sciences will be published in <em>The Cradle of Knowledge: African Journal of Educational and Social Science Research</em> (AJOL), with a 50% waiver of the article processing charges (APC). The discounted fee is KES 6,000.</li></ul><p>Authors are encouraged to take advantage of these opportunities offered by the partner journals.</p><h2>Partners</h2><ul><li><strong>Society of Educational Research and Evaluation in Kenya (SEREK)</strong> — African Journal of Educational and Social Science Research</li><li><strong>Kenya Medical Research Institute (KEMRI)</strong> — African Journal of Health Sciences</li></ul>"}, {"id": "c-tiers", "type": "tiers", "heading": "Sponsorship Opportunities", "intro": "Partner with KAFU to showcase your brand to researchers, innovators, industry leaders and policymakers from around the world.", "items": [{"title": "Platinum", "value": "KES 500,000+", "items": ["Platinum Sponsor advertising space in the book of abstracts", "Short description of the sponsor", "Logo in all conference literature/media, venue and webpage with link", "Free registration for up to four (4) representatives", "15-minute presentation slot in the programme", "Acknowledged during the welcome ceremony", "Exhibition stand during the event"]}, {"title": "Diamond", "value": "KES 300,000 – 499,999", "items": ["Diamond Sponsor advertising space in the book of abstracts", "Short description of the sponsor", "Logo in all conference literature/media, venue and webpage with link", "Free registration for three (3) representatives", "Acknowledged during the welcome ceremony", "Exhibition stand during the event"]}, {"title": "Gold", "value": "KES 200,000 – 299,999", "items": ["Gold Sponsor advertising space in the book of abstracts", "Short description of the sponsor", "Logo in all conference literature/media, venue and webpage with link", "Free registration for two (2) representatives", "Acknowledged during the welcome ceremony", "Exhibition stand during the event"]}, {"title": "Silver", "value": "KES 100,000 – 199,999", "items": ["Silver Sponsor advertising space in the book of abstracts", "Short description of the sponsor", "Logo in all conference literature, venue and webpage with link", "Free registration for one (1) representative", "Acknowledged during the welcome ceremony", "Exhibition stand during the event"]}, {"title": "Bronze", "value": "KES 50,000 – 99,999", "items": ["Logo in all conference literature, venue and webpage with link", "Acknowledged during the welcome ceremony", "Exhibition stand during the conference"]}, {"title": "Sponsor-a-Speaker", "value": "KES 10,000 – 49,999", "items": ["Logo in all conference literature/media, venue and webpage with link", "Specifically acknowledged during the sponsored lecture"]}]}, {"id": "c-cta2", "type": "cta", "heading": "Be Part of KAFU's Innovation Story", "text": "Submit your abstract, register to attend, exhibit your innovation or sponsor the 1st Annual International Conference and Innovation Week 2026.", "buttons": [{"label": "conference2026@kafu.ac.ke", "url": "mailto:conference2026@kafu.ac.ke"}]}]}, "seo_meta": {"title": "1st Annual International Conference and Innovation Week 2026 — KAFU", "description": "Join KAFU's 1st Annual International Conference and Innovation Week, 21-23 October 2026. Call for abstracts, posters and innovation exhibits now open. Deadline: August 31, 2026.", "keywords": "KAFU conference 2026, innovation week, call for abstracts, Kaimosi Friends University, research conference Kenya"}}
JSON, true);

        if (!is_array($data) || empty($data['slug'])) {
            throw new \RuntimeException('ConferencePageSeeder: embedded page JSON failed to decode.');
        }

        CmsContent::create([
            'type'            => $data['type'],
            'title'           => $data['title'],
            'slug'            => $data['slug'],
            'summary'         => $data['summary'],
            'body'            => $data['body'],
            'status'          => $data['status'] ?? 'published',
            'structured_data' => $data['structured_data'],
            'seo_meta'        => $data['seo_meta'],
